def summarize(scores):
    if not scores:
        return None

    total = 0
    highest = scores[0]
    lowest = scores[0]
    passed = 0
    for score in scores:
        total += score
        if score > highest:
            highest = score
        if score < lowest:
            lowest = score
        if score >= 60:
            passed += 1

    return total / len(scores), highest, lowest, passed
